export const money=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n);
export const due=p=>p.mode==='deposit'?Math.round(p.price*p.deposit/100):p.price;
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function garmentSVG(p){let shape='';const c=p.color||'#444';if(p.type==='dress'||p.type==='gown')shape=`<path d="M88 45 Q120 62 152 45 L164 116 Q151 143 156 175 L${p.type==='gown'?194:177} 325 Q120 345 ${p.type==='gown'?46:63} 325 L84 175 Q89 143 76 116Z" fill="${c}"/><path d="M88 45 Q120 100 152 45 M88 165 Q120 177 153 165 M105 178 L91 323 M133 178 L151 327" fill="none" stroke="#888" opacity=".4"/>`;else {shape=`<path d="M84 50 L105 42 Q120 65 135 42 L156 50 L${p.type==='jacket'?198:193} 113 L170 132 L154 100 L157 207 Q120 220 83 207 L86 100 L70 132 L42 113Z" fill="${c}"/><path d="M105 42 L120 68 L135 42 M120 68 L120 210 M86 180 L105 180 M135 180 L154 180" stroke="#999" opacity=".5" fill="none"/>`;if(p.type==='set')shape+=`<path d="M84 220 L156 220 L170 330 L130 330 L120 251 L110 330 L70 330Z" fill="${c}"/><path d="M120 221 L120 251 M96 234 L88 324 M144 234 L151 324" stroke="#888" opacity=".4" fill="none"/>`;}
return `<svg viewBox="0 0 240 370" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrative ${escapeHTML(p.name)}"><defs><linearGradient id="shade${p.id}"><stop stop-color="white" stop-opacity=".16"/><stop offset=".5" stop-color="white" stop-opacity="0"/><stop offset="1" stop-color="black" stop-opacity=".22"/></linearGradient></defs><path d="M120 18v13M90 46l30-15 30 15" fill="none" stroke="#a2a198" stroke-width="2"/>${shape}</svg>`;}
